  class DeviceGuard
  {
  public:
    template<typename T>
    DeviceGuard(T* obj)
      : device(obj->getDevice()),
        lock(device->getMutex())
    {
      device->begin(); // save state
    }

    ~DeviceGuard()
    {
      device->end(); // restore state
    }

  private:
    Device* device;
    std::lock_guard<std::mutex> lock;
  };

  namespace
